def adapt(text):
 pairs=[('Create a single horizontal sprite strip for the game character','Create a single horizontal ISOLATED ARMOR COMPONENT strip for the game character'),
 ('Do not simply copy the still reference pose. Generate distinct animation poses that create a readable cycle or action.','Use actualHurt227 forfourmatchingperspectivesofonlythisarmorcomponent; nofullcharacter animation.'),
 ('Animation action:','Armor component action:'),
 ('This row owns motion only. Spend the variation budget on limb contacts, arm counter-swing, body height, torso lean, head bob, hair bounce, and loop continuity.','This row owns ONLY the specified component fourmatchingHurtperspectives. No body,limbs,head,weapon orwholeoutfit generation.'),
 ('Exactly 4 full-body frames, left to right, in one horizontal row.','Exactly4 isolated complete views ofthe SAME specifiedarmorcomponent, lefttoright; nofullbodyframes.'),
 ('each requested slot must contain exactly one complete full-body pose.','eachrequestedslot mustcontainexactlyonecomplete specifiedarmorcomponent.'),
 ('- Prefer pose, expression, and silhouette changes over decorative effects.','- Prefer requiredcomponentforeshortening only; nofacialexpression/wholebody ordecorativeeffects.'),
 ('- Effects are allowed only when state-relevant, opaque, hard-edged, sprite-like, fully inside the same frame slot, and physically touching or overlapping the character silhouette.','- No effects orcharacter silhouette arepartof thisisolatedarmorrow.'),
 ('- Reject any pose that is cropped, overlaps another pose, crosses into a neighboring frame slot, or creates a separate disconnected component that is not attached to the character.','- Rejectcroppedarmor, unwantedloosefragments orneighbor-slotcrossing. Eachspecifiedisolatedarmorcomponentisintentionallyindependent ofthe character.'),
 ('Preserve the same silhouette, face, proportions, palette, material, and props across every frame.','Preserve the SAME acceptedarmor construction,palette,material,physicalsideandreadabledetail; itsboundschangeonlywithactualHurtperspective,notperframefitnormalization.')]
 audit=[]
 for a,b in pairs:
  assert text.count(a)==1,(a,text.count(a));text=text.replace(a,b);audit.append({'before':a,'after':b,'count':1})
 assert 'full-body frames' not in text and 'complete full-body pose' not in text and 'component that is not attached to the character' not in text
 return text,audit

